create table if not exists site_domains (id bigserial primary key,tenant_key varchar(120) not null,site_key varchar(120) not null,domain_name varchar(253) not null,environment varchar(24) not null,verification_token varchar(180) not null,verification_status varchar(32) not null,certificate_status varchar(32) not null,redirect_target varchar(500),last_checked_at timestamp with time zone,created_at timestamp with time zone not null,updated_at timestamp with time zone not null,constraint uk_site_domain_name unique(domain_name));
create table if not exists site_domain_events (id bigserial primary key,domain_id bigint not null,event_type varchar(40) not null,status varchar(40) not null,detail varchar(500),created_at timestamp with time zone not null,constraint fk_site_domain_event foreign key(domain_id) references site_domains(id));
create index if not exists ix_site_domains_scope on site_domains(tenant_key,site_key);
create index if not exists ix_site_domain_events_domain on site_domain_events(domain_id,created_at desc);
